// FFBE JP Memorial — combined runtime hooks (v7).
//   Module 1: plate-swap
//   Module 2: LB/SLB CG fetch
//     - PRE-FETCH (curl) on LibraryUnitDetailScene::setUnitLayout — silent
//       background download so most users never see a dialog
//     - On scene-reopen, also resets the user's "cancelled" decision so a
//       fresh visit reprompts
//     - Safety-net on existsLocalFile: if file still missing on Play tap,
//       calls our Java helper LBDialog.requestDownload via JNI to show a
//       Material AlertDialog with Download / Cancel + progress bar
//
// JNI is invoked through cocos2d::JniHelper::getStaticMethodInfo +
// JNIEnv->CallStaticVoidMethodA — Frida 17 gadget has no Java bridge,
// so we go raw.

const WRITABLE_DIR = '/data/data/com.square_enix.ffbejpn/files/';

// Public release: persistent diagnostic file logging is disabled.
function dbg(msg) {}

dbg('=== script v7 boot ===');

// libc::system for curl
let _system = null;
try {
    const libc = Process.getModuleByName('libc.so');
    const sysAddr = libc.findExportByName('system');
    if (sysAddr) {
        _system = new NativeFunction(sysAddr, 'int', ['pointer']);
        dbg('libc::system @ ' + sysAddr);
    }
} catch (e) {
    dbg('libc::system FAIL: ' + e);
}

function findExport_(name) {
    if (Module.getGlobalExportByName) {
        try { return Module.getGlobalExportByName(name); } catch (_) {}
    }
    for (const m of Process.enumerateModules()) {
        const x = m.findExportByName ? m.findExportByName(name) : null;
        if (x) return x;
    }
    return null;
}

// ============================================================
// MODULE 1: PLATE SWAP
// ============================================================
try {
    const PAYLOAD_DIR = '/data/user/0/com.square_enix.ffbejpn/files/plate_swaps';
    const OFF_initWithImageData = 0x2128b38;

    const libgame = Process.enumerateModules().find(m => m.name === 'libgame.so');
    if (!libgame) throw new Error('libgame.so not loaded');

    function xport(name, ret, argT) {
        let p = null;
        if (Module.findGlobalExportByName) p = Module.findGlobalExportByName(name);
        if (!p) {
            for (const m of Process.enumerateModules()) {
                if (m.findExportByName) { p = m.findExportByName(name); if (p) break; }
            }
        }
        if (!p) throw new Error('cannot resolve symbol: ' + name);
        return new NativeFunction(p, ret, argT);
    }
    const open  = xport('open',  'int',     ['pointer','int','int']);
    const read  = xport('read',  'ssize_t', ['int','pointer','size_t']);
    const close = xport('close', 'int',     ['int']);
    const lseek = xport('lseek', 'int64',   ['int','int64','int']);

    function readFile(path) {
        const cpath = Memory.allocUtf8String(path);
        const fd = open(cpath, 0, 0);
        if (fd < 0) return null;
        const sz = lseek(fd, 0, 2).toNumber();
        lseek(fd, 0, 0);
        const buf = Memory.alloc(sz);
        let total = 0;
        while (total < sz) {
            const n = read(fd, buf.add(total), sz - total);
            if (n <= 0) break;
            total += n;
        }
        close(fd);
        return { ptr: buf, len: sz };
    }

    const manifestRaw = readFile(PAYLOAD_DIR + '/manifest.json');
    if (!manifestRaw) {
        dbg('[plate-swap] manifest missing; exiting without swap');
    } else {
        const manifest = JSON.parse(manifestRaw.ptr.readUtf8String(manifestRaw.len));
        const bySize = {};
        let loaded = 0;
        for (const [sizeStr, name] of Object.entries(manifest.by_size)) {
            const f = readFile(PAYLOAD_DIR + '/' + name);
            if (f) { bySize[sizeStr] = f; loaded++; }
        }
        dbg('[plate-swap] loaded ' + loaded + ' English plates');

        // New chapter plates share sizes with unrelated story images.
        // Check original encrypted OR decoded PNG bytes before replacing them.
        // BEGIN PLATE PREFIX GUARD
        function matchesPlatePrefix(data, prefixes) {
            if (!prefixes) return true;
            try {
                const bytes = new Uint8Array(data.readByteArray(64));
                return prefixes.some(prefix => {
                    for (let i = 0; i < 64; i++) {
                        if (bytes[i] !== prefix[i]) return false;
                    }
                    return true;
                });
            } catch (_) { return false; }
        }
        // END PLATE PREFIX GUARD
        const prefixGuards = {};
        for (const [size, values] of Object.entries(manifest.prefix_guards || {})) {
            prefixGuards[size] = values.map(hex => Uint8Array.from(
                hex.match(/../g).map(pair => parseInt(pair, 16))));
        }

        Interceptor.attach(libgame.base.add(OFF_initWithImageData), {
            onEnter(args) {
                const len = args[2].toInt32();
                const rep = bySize[String(len)];
                if (!rep) return;
                if (!matchesPlatePrefix(args[1], prefixGuards[String(len)])) return;
                args[1] = rep.ptr;
                args[2] = ptr(rep.len);
            }
        });
        dbg('[plate-swap] hook armed');
    }
} catch (e) {
    dbg('[plate-swap] ERROR: ' + e + ' :: ' + (e.stack || ''));
}

// ============================================================
// MODULE 2: LB/SLB CG fetch via Java AlertDialog (LBDialog class)
// ============================================================
try {
    const CDN_BASE = "https://cdn.luminest.io/ffbe/movies/";
    const CURL = "/system/bin/curl";

    const SYM_EXISTS_LOCAL_FILE =
        "_ZN11CommonUtils15existsLocalFileERKNSt6__ndk112basic_stringIcNS0_11char_traitsIcEENS0_9allocatorIcEEEE";
    const SYM_SET_UNIT_LAYOUT =
        "_ZN22LibraryUnitDetailScene13setUnitLayoutEP7UnitMst";
    const SYM_GET_LB_ID = "_ZN7UnitMst15getLimitBurstIDEv";
    const SYM_LB_MST_SHARED = "_ZN17LimitBurstMstList6sharedEv";
    const SYM_OBJECT_FOR_KEY = "_ZN7cocos2d12__Dictionary12objectForKeyEl";
    const SYM_JNIHELPER_GETSMI =
        "_ZN7cocos2d9JniHelper19getStaticMethodInfoERNS_14JniMethodInfo_EPKcS4_S4_";

    const JAVA_CLASS = "com/square_enix/ffbejpn/LBDialog";

    function readStdString(p) {
        if (p.isNull()) return null;
        try {
            const flag = p.readU8();
            if (flag & 1) {
                const size = p.add(0x08).readU64().toNumber();
                const data = p.add(0x10).readPointer();
                return data.readUtf8String(size);
            } else {
                const size = flag >> 1;
                return p.add(0x01).readUtf8String(size);
            }
        } catch (e) { return null; }
    }

    function isLBFile(name) {
        if (!name) return false;
        if (!/\.(usm|cpk)$/i.test(name)) return false;
        return /^(SLB_|LB_)/i.test(name) || /^LBMovie/i.test(name);
    }

    // Files referenced by JP MST but not available from any known dump.
    // Treat these as "not downloadable" — no dialog, fall back to sprite anim.
    const UNAVAILABLE = new Set([
        "LB_LBM_lapis4new_JP.usm",
        "LB_LBO_lapis4new_jp.usm",
        "SLB_LBA_v.usm",
        "SLB_LBB_v.usm",
        "SLB_LBC_v.usm",
        "SLB_LBD_v.usm",
        "SLB_LBE_v.usm",
        "SLB_LBF_v.usm",
        "SLB_LBG.usm",
        "SLB_LBH.usm",
        "SLB_LBI.usm",
        "SLB_LBJ.usm",
        "SLB_LBK.usm",
        "SLB_LBL.usm",
        "SLB_LBM.usm",
        "SLB_LBN.usm",
        "SLB_LSM.usm",
        "SLB_LSN.usm",
        "SLB_Riko.usm",
    ]);

    // ---- JNI bridge ----
    let _getStaticMethodInfo = null;
    function initJni() {
        const a = findExport_(SYM_JNIHELPER_GETSMI);
        if (!a) { dbg("[lb_fetch] JniHelper::getStaticMethodInfo NOT FOUND"); return; }
        _getStaticMethodInfo = new NativeFunction(a, 'bool',
            ['pointer','pointer','pointer','pointer']);
        dbg("[lb_fetch] JniHelper @ " + a);
    }

    // JNIEnv function-table indices (8 bytes each on arm64)
    const JNI_NewStringUTF          = 167 * 8;
    const JNI_DeleteLocalRef        =  23 * 8;
    const JNI_CallStaticVoidMethodA = 143 * 8;

    // args: array of strings (→ jstring) or numbers (→ jint, low 32 bits)
    function jniCallStaticVoid(className, methodName, sig, args) {
        if (!_getStaticMethodInfo) return false;
        const info = Memory.alloc(32);                         // env, classID, methodID
        const cls = Memory.allocUtf8String(className);
        const mth = Memory.allocUtf8String(methodName);
        const sg  = Memory.allocUtf8String(sig);
        const ok = _getStaticMethodInfo(info, cls, mth, sg);
        if (!ok) {
            dbg("[lb_fetch] getStaticMethodInfo FAIL: " + methodName);
            return false;
        }
        const env      = info.readPointer();
        const classID  = info.add(8).readPointer();
        const methodID = info.add(16).readPointer();
        const fnTable  = env.readPointer();

        const NewStringUTF = new NativeFunction(
            fnTable.add(JNI_NewStringUTF).readPointer(),
            'pointer', ['pointer','pointer']);
        const CallStaticVoidA = new NativeFunction(
            fnTable.add(JNI_CallStaticVoidMethodA).readPointer(),
            'void', ['pointer','pointer','pointer','pointer']);
        const DeleteLocalRef = new NativeFunction(
            fnTable.add(JNI_DeleteLocalRef).readPointer(),
            'void', ['pointer','pointer']);

        const localRefs = [];
        const jvalues = Memory.alloc(Math.max(8, 8 * args.length));
        for (let i = 0; i < args.length; i++) {
            const a = args[i];
            if (typeof a === 'string') {
                const c = Memory.allocUtf8String(a);
                const j = NewStringUTF(env, c);
                localRefs.push(j);
                jvalues.add(i * 8).writePointer(j);
            } else if (typeof a === 'number') {
                jvalues.add(i * 8).writeS32(a | 0);   // jint = 4 bytes, low end
            } else {
                dbg("[lb_fetch] unsupported arg type: " + typeof a);
                return false;
            }
        }
        try {
            CallStaticVoidA(env, classID, methodID, jvalues);
        } finally {
            for (const j of localRefs) DeleteLocalRef(env, j);
        }
        return true;
    }

    function lbDialogRequest(filename) {
        const url = CDN_BASE + filename;
        const dest = WRITABLE_DIR + filename;
        return jniCallStaticVoid(JAVA_CLASS, "requestDownload",
            "(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;)V",
            [filename, url, dest]);
    }

    function lbDialogReset(filename) {
        return jniCallStaticVoid(JAVA_CLASS, "resetCancellation",
            "(Ljava/lang/String;)V", [filename]);
    }

    // ---- Silent curl pre-fetch (most users never see a dialog) ----
    const inFlight = new Set();
    function shellEsc(s) { return "'" + s.replace(/'/g, "'\\''") + "'"; }
    function fireCurl(filename, label) {
        if (!_system || inFlight.has(filename)) return;
        inFlight.add(filename);
        const url = CDN_BASE + filename;
        const dest = WRITABLE_DIR + filename;
        const part = dest + ".part";
        const cmd =
            "(if [ -s " + shellEsc(dest) + " ]; then " +
            "  echo \"[curl] cached " + filename + "\" >> " + shellEsc(LOG_PATH) + "; " +
            " else " +
            "  " + CURL + " -fsSL --max-time 180 -o " + shellEsc(part) + " " + shellEsc(url) +
            "  && mv " + shellEsc(part) + " " + shellEsc(dest) +
            "  && echo \"[curl] done " + filename + "\" >> " + shellEsc(LOG_PATH) +
            "  || echo \"[curl] FAIL " + filename + " rc=$?\" >> " + shellEsc(LOG_PATH) + "; " +
            "  rm -f " + shellEsc(part) + "; " +
            " fi) &";
        dbg("[lb_fetch] " + label + " " + filename);
        _system(Memory.allocUtf8String(cmd));
    }

    // ---- Pre-fetch + cancellation reset on scene-open ----
    function armPrefetch() {
        const setUL = findExport_(SYM_SET_UNIT_LAYOUT);
        const a1 = findExport_(SYM_GET_LB_ID);
        const a2 = findExport_(SYM_LB_MST_SHARED);
        const a3 = findExport_(SYM_OBJECT_FOR_KEY);
        if (!setUL || !a1 || !a2 || !a3) {
            dbg("[lb_fetch] prefetch: missing symbol(s)");
            return;
        }
        const getLbId = new NativeFunction(a1, 'int', ['pointer']);
        const lbListShared = new NativeFunction(a2, 'pointer', []);
        const objectForKey = new NativeFunction(a3, 'pointer', ['pointer','int64']);
        Interceptor.attach(setUL, {
            onEnter(args) {
                const unitMst = args[1];
                if (unitMst.isNull()) return;
                try {
                    const lbId = getLbId(unitMst);
                    if (lbId <= 0) return;
                    const list = lbListShared();
                    if (list.isNull()) return;
                    const lbMst = objectForKey(list, lbId);
                    if (lbMst.isNull()) return;
                    const cg = readStdString(lbMst.add(0x1e0));
                    if (!cg || !isLBFile(cg)) return;
                    if (UNAVAILABLE.has(cg)) return;          // skip known-unavailable files
                    fireCurl(cg, "PREFETCH");
                    lbDialogReset(cg);          // clear stale cancel/fail
                } catch (e) {
                    dbg("[lb_fetch] prefetch error: " + e);
                }
            }
        });
        dbg("[lb_fetch] prefetch hook armed @ " + setUL);
    }

    // ---- Safety-net: if user taps Play before file is local, prompt ----
    function armSafetyNet() {
        const sym = findExport_(SYM_EXISTS_LOCAL_FILE);
        if (!sym) { dbg("[lb_fetch] safety-net: existsLocalFile NOT FOUND"); return; }
        Interceptor.attach(sym, {
            onEnter(args) { this.filename = readStdString(args[0]); },
            onLeave(retval) {
                const fn = this.filename;
                if (!isLBFile(fn)) return;
                if (retval.toInt32() !== 0) return;       // file present, all good
                if (UNAVAILABLE.has(fn)) return;          // never prompt for these
                lbDialogRequest(fn);                       // shows AlertDialog (idempotent)
            }
        });
        dbg("[lb_fetch] safety-net hook armed @ " + sym);
    }

    initJni();
    armPrefetch();
    armSafetyNet();

    // ---- Version check on app launch ----
    // Bump PATCH_VERSION whenever you ship a new APK. Keep the JSON manifest
    // (uploaded next to the movies) in sync; when manifest's "version" is
    // greater than ours, the user sees an update prompt.
    const PATCH_VERSION = 207;
    const MANIFEST_URL   = "https://raw.githubusercontent.com/luminest-llc/ffbe-memorial-downloads/beta/channels/beta/patch_version.json";
    const DOWNLOAD_URL   = "https://ffbe.luminest.io/downloads/beta/";
    setTimeout(function () {
        try {
            jniCallStaticVoid(JAVA_CLASS, "checkForUpdate",
                "(ILjava/lang/String;Ljava/lang/String;)V",
                [PATCH_VERSION, MANIFEST_URL, DOWNLOAD_URL]);
            jniCallStaticVoid("O1/DownloadNotice", "show", "()V", []);
            dbg("[update] check fired (local v" + PATCH_VERSION + ")");
        } catch (e) {
            dbg("[update] check FAIL: " + e);
        }
    }, 2000);   // small delay so the activity is created before the dialog tries to attach
} catch (e) {
    dbg('[lb_fetch] ERROR: ' + e + ' :: ' + (e.stack || ''));
}

dbg('=== script v7 boot complete ===');

