// Imported events use normal saved parties, including native swipe selection.
// Other playback missions retain the game's prescribed temporary party.
(function(){
 let attempts=0;
 const timer=setInterval(function(){
  const game=Process.findModuleByName('libgame.so');
  if(!game){if(++attempts>120)clearInterval(timer);return;}
  clearInterval(timer);if(Process.arch!=='arm64')return;
  const init=game.getExportByName('_ZN20ReadyForMissionScene10initializeEv');
  const getType=game.getExportByName('_ZN28ReadyForPlaybackMissionScene12getPartyTypeEv');
  const getTypeThunk=game.getExportByName('_ZThn16_N28ReadyForPlaybackMissionScene12getPartyTypeEv');
  const playbackVtable=game.getExportByName('_ZTV28ReadyForPlaybackMissionScene').add(16);
  if(!init.equals(game.base.add(0x197c7a4))||!getType.equals(game.base.add(0x1adbfac))||getType.readU32()!==0x52800160||getTypeThunk.readU32()!==0x52800160||game.base.add(0x1adbfc0).readU32()!==0xb9479001)return;
  const restoreNormal=new NativeFunction(game.getExportByName('_ZN13PartyDeckUtil22changeDefaultPartyTypeEv'),'void',[]);
  // This static method's mangled signature has no C++ this argument.
  const setInfoType=new NativeFunction(game.getExportByName('_ZN17UserPartyInfoList16setPartyInfoTypeEi'),'void',['int']);
  function isImported(scene){return scene.readPointer().equals(playbackVtable)&&!!SIDE_STORY_PARTIES.books[scene.add(0x790).readS32()];}
  Interceptor.attach(init,{onEnter(args){
   if(!isImported(args[0]))return;
   restoreNormal();setInfoType(0);
  }});
  function overrideType(address,adjust){
   Interceptor.attach(address,{onEnter(args){this.imported=isImported(args[0].sub(adjust));},onLeave(value){if(this.imported)value.replace(1);}});
  }
  overrideType(getType,0);overrideType(getTypeThunk,16);
 },250);
})();
